  (
    'd1000001-0000-4000-8000-100100000020',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The United Nations (UN) is a global intergovernmental organization established by the signing of the Charter of the United Nations on 26 June 1945 with the articulated mission of maintaining international peace and security, to develop friendly relations among states, to promote international cooperation, and to serve as a centre for harmonizing the actions of states in achieving those goals."}]},{"type":"paragraph","content":[{"type":"text","text":"The United Nations headquarters is located in New York City, with several other offices located in Geneva, Nairobi, Vienna and The Hague."}]}]},"keywords":[{"id":"kw1","text":"Geneva"},{"id":"kw2","text":"26 June 1945"},{"id":"kw3","text":"located"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"United Nations","pageid":31769,"revision_id":1363446255,"url":"https://en.wikipedia.org/wiki/United_Nations","license":"CC BY-SA 4.0","retrieved_at":"2026-07-11T15:06:19.295Z"}}'::jsonb,
