    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Food52 is a recipe and cookware website. Founded in 2009 by Amanda Hesser and Merrill Stubbs, formerly of the New York Times, its website is intended as a platform for users to publish recipes and discuss cooking. The company also produces its own books."}]}]},"keywords":[{"id":"kw1","text":"2009"},{"id":"kw2","text":"website"},{"id":"kw3","text":"York"},{"id":"kw4","text":"Amanda"},{"id":"kw5","text":"New"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Food52","pageid":76319386,"revision_id":1359439531,"url":"https://en.wikipedia.org/wiki/Food52","license":"CC BY-SA 4.0","retrieved_at":"2026-07-11T15:06:19.295Z"}}'::jsonb,
