    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Goleniowy [ɡɔlɛˈɲɔvɨ] is a village in the administrative district of Gmina Szczekociny, within Zawiercie County, Silesian Voivodeship, in southern Poland. The Polish poet Wespazjan Kochowski (1660-1700) lived in Golenowy."}]}]},"keywords":[{"id":"kw1","text":"County"},{"id":"kw2","text":"1660"},{"id":"kw3","text":"Goleniowy"},{"id":"kw4","text":"Silesian"},{"id":"kw5","text":"Golenowy"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Goleniowy","pageid":21263695,"revision_id":1351027517,"url":"https://en.wikipedia.org/wiki/Goleniowy","license":"CC BY-SA 4.0","retrieved_at":"2026-07-11T15:06:19.295Z"}}'::jsonb,
